def _tier3_process_trace_fields(snapshot: Any | None) -> dict[str, Any]:
    """Publish bounded owner evidence during the run, before shutdown overwrites it."""

    return {
        f"source_stream_process_{kind}_samples": copy.deepcopy(
            list(getattr(snapshot, f"{kind}_samples", ()))[-64:]
        )
        for kind in ("dispatch", "attempt", "terminal")
    }


def _tier3_unresolved_process_failure(snapshot: Any | None) -> str:
    """Return only a currently actionable process-domain failure."""

    if snapshot is None:
        return ""
    supervisor = getattr(snapshot, "supervisor", None)
    incident = str(getattr(supervisor, "last_failure_reason", "") or "")
    if not incident:
        return ""
    stop_status = str(getattr(snapshot, "stop_status", "") or "")
    unresolved = bool(
        getattr(supervisor, "hard_stall", False)
        or int(getattr(supervisor, "quarantined_workers", 0) or 0) > 0
        or getattr(supervisor, "resource_headroom_limited", False)
        or stop_status.startswith(("STOP_FAILED", "STOP_TIMEOUT"))
    )
    return incident if unresolved else ""


def tier3_candidate_service_family(node: Node) -> str:
    """Return the validation family from the candidate protocol only."""

    protocol = str(node.protocol or "").strip().lower()
    if not protocol and "://" in str(node.uri or ""):
        protocol = str(node.uri or "").split("://", 1)[0].strip().lower()
    return Tier3CandidateScheduler.normalize_family(protocol or "unknown")


def _tier3_structural_profile_token(
    value: Any,
    fallback: str = "none",
) -> str:
    text = str(value or "").strip().lower()
    if not text:
        return fallback
    safe = "".join(
        character
        if character.isalnum() or character in {".", "-", "_", ":", "/"}
        else "_"
        for character in text
    )
    return safe[:96] or fallback


def tier3_candidate_service_profile_components(node: Node) -> tuple[str, ...]:
    """Return source- and credential-independent connection structure."""

    extra = node.extra if isinstance(node.extra, dict) else {}
    transport = _tier3_structural_profile_token(
        node.network
        or extra.get("network")
        or extra.get("transport")
        or node.plugin
        or extra.get("plugin"),
        "unknown",
    )
    security = _tier3_structural_profile_token(
        node.security
        or extra.get("security")
        or ("tls" if bool(node.tls) else "plain"),
        "plain",
    )
    auth_mode = "+".join(
        part
        for part, present in (
            ("username", bool(getattr(node, "username", "") or extra.get("username"))),
            ("uuid", bool(getattr(node, "uuid", "") or extra.get("uuid"))),
            ("password", bool(getattr(node, "password", "") or extra.get("password"))),
        )
        if present
    ) or "none"
    encryption = _tier3_structural_profile_token(
        node.encryption
        or node.method
        or extra.get("cipher")
        or extra.get("method")
        or extra.get("encryption"),
    )
    flow = _tier3_structural_profile_token(
        getattr(node, "flow", "") or extra.get("flow"),
    )
    fingerprint = _tier3_structural_profile_token(
        extra.get("client-fingerprint")
        or extra.get("client_fingerprint")
        or extra.get("fingerprint"),
    )
    try:
        port = int(node.port or 0)
    except (TypeError, ValueError):
        port = 0
    if port <= 0:
        port_category = "unknown"
    elif port in {80, 443, 2053, 2083, 2087, 2095, 2096, 8080, 8443}:
        # This is a connection class, not an endpoint identity. Group common
        # web-facing ports so equivalent front doors can share yield evidence.
        port_category = "web_service"
    elif port in {1080, 8388}:
        port_category = "proxy_service"
    elif port < 1024:
        port_category = "system_service"
    elif port < 49152:
        port_category = "registered_service"
    else:
        port_category = "dynamic_service"
    sni_value = str(
        node.sni or extra.get("sni") or extra.get("servername") or ""
    ).strip().lower()
    host_value = str(
        node.host or extra.get("host") or extra.get("ws_host") or ""
    ).strip().lower()
    if sni_value and host_value:
        host_shape = (
            "sni_host_same"
            if sni_value == host_value
            else "sni_host_distinct"
        )
    elif sni_value:
        host_shape = "sni_only"
    elif host_value:
        host_shape = "host_only"
    else:
        host_shape = "none"
    path_value = str(
        node.path or extra.get("path") or extra.get("ws_path") or ""
    ).strip()
    path_body, separator, query = path_value.partition("?")
    path_segments = [part for part in path_body.split("/") if part]
    if not path_value:
        path_shape = "none"
    elif not path_segments:
        path_shape = "root"
    elif len(path_segments) == 1:
        path_shape = "one_segment"
    else:
        path_shape = "multi_segment"
    if separator and query:
        path_shape = f"{path_shape}_query"
    return (
        tier3_candidate_service_family(node),
        auth_mode,
        encryption,
        transport,
        security,
        flow,
        fingerprint,
        port_category,
        host_shape,
        path_shape,
    )


def tier3_candidate_service_profile_levels(
    components: tuple[str, ...],
) -> tuple[str, ...]:
    """Build HMAC-only L0-L3 connection-structure cohort keys."""

    (
        service_family,
        auth_mode,
        encryption,
        transport,
        security,
        flow,
        fingerprint,
        port_category,
        host_shape,
        path_shape,
    ) = components

    def meaningful(value: str) -> bool:
        return str(value or "").strip().lower() not in {
            "",
            "none",
            "unknown",
            "default",
            "aggregate",
        }

    levels: list[tuple[str, ...]] = [(service_family,)]
    levels.append(
        tuple(
            [service_family]
            + [
                value
                for value in (transport, security)
                if meaningful(value)
            ]
        )
    )
    levels.append(
        tuple(
            list(levels[-1])
            + [
                value
                for value in (auth_mode, encryption, flow, fingerprint)
                if meaningful(value)
            ]
        )
    )
    levels.append(
        tuple(
            list(levels[-1])
            + [
                value
                for value in (port_category, host_shape, path_shape)
                if meaningful(value)
            ]
        )
    )
    profiles: list[str] = []
    previous: tuple[str, ...] | None = None
    for level, values in enumerate(levels):
        if values == previous:
            continue
        previous = values
        payload = json.dumps(values, ensure_ascii=True, separators=(",", ":"))
        profiles.append(
            runtime_scoped_hmac(
                payload,
                namespace=f"candidate-service-profile-l{level}",
                length=24,
            )
        )
    return tuple(profiles)


def tier3_candidate_origin_service_profile(
    *,
    source_root: str,
    source_unit_id: str,
    feature_key: Tier3CandidateFeatureKey,
) -> str:
    """Return the source-independent complete structural leaf.

    ``source_root`` and ``source_unit_id`` remain in the compatibility
    signature for one report-schema cycle, but they must not split learning.
    The complete L3 profile is already a process-scoped HMAC and contains no
    source identity, endpoint address, credential, or literal host/path.
    """

    del source_root, source_unit_id
    profiles = tuple(feature_key.ordered_service_profiles())
    return profiles[-1] if profiles else feature_key.service_family


def tier3_runtime_feature_report() -> dict[str, Any]:
    build_identity = tier3_build_identity()
    packaged = bool(getattr(sys, "frozen", False))
    identity_match = bool(build_identity.get("identity_match"))
    manager_path = Path(__file__)
    source_hash = "unavailable"
    try:
        source_hash = hashlib.sha256(manager_path.read_bytes()).hexdigest()[:16]
    except OSError:
        pass
    return {
        "feature_marker": str(build_identity["build_id"]),
        "build_id": str(build_identity["build_id"]),
        "build_components": dict(
            build_identity.get("components", {})
        ),
        "executable_sha256": str(
            build_identity.get("executable_sha256") or "unavailable"
        ),
        "declared_executable_sha256": str(
            build_identity.get("declared_executable_sha256") or "unavailable"
        ),
        "identity_match": identity_match,
        "performance_sample_valid": bool(not packaged or identity_match),
        "source_stream_report_schema_version": (
            TIER3_SOURCE_STREAM_REPORT_SCHEMA_VERSION
        ),
        "manager_path": str(manager_path),
        "manager_sha256": source_hash,
        "packaged": packaged,
        "executable": str(getattr(sys, "executable", "")),
    }


def _tier3_source_unit_has_observed_fact(unit: dict[str, Any]) -> bool:
    return bool(
        unit.get("ok")
        or not bool(unit.get("pending", True))
        or str(unit.get("status") or "pending").strip().lower() != "pending"
        or str(unit.get("error") or "").strip()
        or int(unit.get("deadline_actual_ms", 0) or 0) > 0
        or int(unit.get("transport_elapsed_ms", 0) or 0) > 0
        or int(unit.get("node_count", 0) or 0) > 0
        or bool(unit.get("runtime_source_route_dispatch_deferred"))
    )


def _tier3_source_unit_key(unit: dict[str, Any]) -> str:
    return str(unit.get("id") or unit.get("value") or "default")


def _tier3_source_unit_fact_rank(unit: dict[str, Any]) -> int:
    if bool(unit.get("ok")):
        return 4
    pending = bool(unit.get("pending", True)) or (
        str(unit.get("status") or "pending").strip().lower() == "pending"
    )
    if not pending and _tier3_source_unit_has_observed_fact(unit):
        return 3
    if _tier3_source_unit_has_observed_fact(unit):
        return 2
    return 1


def _tier3_source_unit_retry_due(unit: dict[str, Any]) -> bool:
    return bool(
        not unit.get("ok")
        and (unit.get("pending") or unit.get("retryable"))
        and _tier3_source_unit_has_observed_fact(unit)
    )


def _tier3_source_root_retry_due(source: dict[str, Any]) -> bool:
    if bool(source.get("ok")):
        return False
    units = [
        unit
        for unit in (source.get("units") or [])
        if isinstance(unit, dict)
    ]
    if any(_tier3_source_unit_retry_due(unit) for unit in units):
        return True
    # Config materialization intentionally exposes roots as pending before
    # transport begins.  The initial dispatch lease owns that work; it must
    # not also be interpreted as a retry.  A positive fact revision is
    # assigned only when a dispatch lease produces a terminal/deferred fact.
    return bool(
        (source.get("pending") or source.get("retryable"))
        and int(source.get("source_supply_fact_revision", 0) or 0) > 0
    )


def _tier3_source_unit_is_deterministic_404(unit: dict[str, Any]) -> bool:
    if bool(unit.get("ok")) or bool(unit.get("pending")):
        return False
    if bool(unit.get("retryable")):
        return False
    try:
        status_code = int(
            unit.get("http_status", unit.get("status_code", 0)) or 0
        )
    except (TypeError, ValueError):
        status_code = 0
    error = str(unit.get("error") or "").strip().lower()
    return status_code == 404 or "404" in error or "not found" in error


def _tier3_conditional_refresh_entry(
    configured_entry: dict[str, Any],
    current_source: dict[str, Any] | None,
) -> dict[str, Any] | None:
    """Keep same-generation deterministic 404 units out of refresh work."""

    entry = dict(configured_entry)
    source_type = str(entry.get("type") or "subscription_url").strip().lower()
    if source_type not in {"github", "github_repo", "github_repos"}:
        return entry
    configured_paths = [
        str(path or "").strip()
        for path in (entry.get("candidate_paths") or [])
        if str(path or "").strip()
    ]
    if not configured_paths or not isinstance(current_source, dict):
        return entry
    units_by_id = {
        _tier3_source_unit_key(unit).strip().lstrip("/").lower(): unit
        for unit in (current_source.get("units") or [])
        if isinstance(unit, dict)
    }
    refresh_paths: list[str] = []
    for path in configured_paths:
        unit = units_by_id.get(path.lstrip("/").lower())
        if unit is not None and _tier3_source_unit_is_deterministic_404(unit):
            continue
        refresh_paths.append(path)
    if not refresh_paths:
        return None
    entry["candidate_paths"] = refresh_paths
    return entry


def _merge_tier3_source_units(
    previous_units: list[dict[str, Any]],
    current_units: list[dict[str, Any]],
) -> list[dict[str, Any]]:
    order: list[str] = []
    merged: dict[str, dict[str, Any]] = {}
    for raw_unit in [*previous_units, *current_units]:
        if not isinstance(raw_unit, dict):
            continue
        unit = dict(raw_unit)
        key = _tier3_source_unit_key(unit)
        existing = merged.get(key)
        if existing is None:
            order.append(key)
            merged[key] = unit
            continue
        existing_rank = _tier3_source_unit_fact_rank(existing)
        current_rank = _tier3_source_unit_fact_rank(unit)
        if current_rank < existing_rank:
            continue
        updated = dict(existing)
        updated.update(unit)
        merged[key] = updated
    return [merged[key] for key in order]


def _merge_tier3_source_root_state(
    previous: dict[str, Any],
    source: dict[str, Any],
) -> dict[str, Any]:
    previous_fact_revision = max(
        0, int(previous.get("source_supply_fact_revision", 0) or 0)
    )
    source_fact_revision = max(
        0, int(source.get("source_supply_fact_revision", 0) or 0)
    )
    if previous_fact_revision > source_fact_revision:
        return dict(previous)
    source_pending = bool(source.get("pending")) or (
        str(source.get("status") or "").strip().lower() == "pending"
    )
    previous_terminal = bool(previous.get("ok")) or (
        bool(previous)
        and not bool(previous.get("pending"))
        and str(previous.get("status") or "").strip().lower()
        in {"failed", "ok", "partial"}
    )
    incoming_units = [
        dict(unit)
        for unit in (source.get("units") or [])
        if isinstance(unit, dict)
    ]
    if (
        previous_terminal
        and source_pending
        and not any(_tier3_source_unit_has_observed_fact(unit) for unit in incoming_units)
    ):
        # An older aggregate/pending snapshot can be published after an
        # independent retry terminal. Keep the mature root fact; retry_due is
        # represented by the source-supply lease state rather than by revoking
        # the last completed result.
        return dict(previous)
    updated = dict(previous)
    updated.update(source)
    previous_units = [
        dict(unit)
        for unit in (previous.get("units") or [])
        if isinstance(unit, dict)
    ]
    current_units = incoming_units
    # Retry reports are partial current-generation observations. Merge by unit
    # identity and fact maturity so a later aggregate 404 or pending snapshot
    # cannot revoke successful protocol units already streamed to ingress.
    if current_units:
        updated["units"] = _merge_tier3_source_units(
            previous_units,
            current_units,
        )
    else:
        updated["units"] = (
            previous_units
            if any(_tier3_source_unit_has_observed_fact(unit) for unit in previous_units)
            else []
        )
    units = [
        dict(unit)
        for unit in (updated.get("units") or [])
        if isinstance(unit, dict)
    ]
    updated["units"] = units
    # Root success is a monotonic current-generation fact: once any unit has
    # produced a parse-valid payload, a later partial/pending retry snapshot
    # must not revoke that success.  Sibling retryability remains represented
    # by the merged unit states below.
    root_ok = bool(
        previous.get("ok")
        or source.get("ok")
        or any(unit.get("ok") for unit in units)
    )
    if root_ok:
        updated["ok"] = True
        updated["pending"] = False
        updated["status"] = (
            "partial"
            if units and any(not unit.get("ok") for unit in units)
            else "ok"
        )
        updated["retryable"] = any(
            _tier3_source_unit_retry_due(unit) for unit in units
        )
        return updated
    still_pending = bool(source.get("pending")) or (
        str(source.get("status") or "").strip().lower() == "pending"
    )
    updated["ok"] = False
    updated["pending"] = still_pending
    updated["status"] = "pending" if still_pending else "failed"
    unit_retryable = any(_tier3_source_unit_retry_due(unit) for unit in units)
    updated["retryable"] = bool(
        (
            source.get("retryable")
            if "retryable" in source
            else previous.get("retryable")
        )
        or unit_retryable
    )
    return updated


def _tier3_can_apply_legacy_aggregate_root_counts(
    sources: list[dict[str, Any]],
) -> bool:
    return not any(
        _tier3_source_unit_has_observed_fact(unit)
        for source in sources
        for unit in (source.get("units") or [])
        if isinstance(unit, dict)
    )


