        self._tier3a_health_waiters_lock = threading.Lock()
        self._tier3a_health_waiters: dict[str, dict[str, Any]] = {}
        self._tier3a_health_check_sequence = 0
        self._tier3a_health_retry_scheduled = False
        self.last_tier3a_health_check_monotonic = 0.0
