    def compact_tiers_count_status(self) -> dict[str, Any]:
        """Read scalar counts once under lock, without clones or ledger maintenance.

        ALIVE/SLOW is usable unless the runtime-health ledger overlays it.
        Strict tiers additionally apply testing.primary_gateway_max_latency_ms
        to latency_ms and honor latency_policy_state=over_limit; Tier3 retains
        its ALIVE/SLOW policy (slow_threshold_ms classifies, not excludes).
        Display eligibility and origin predicates are the existing pool rules.
        Physical Tier1 groups count once, in the tier and in the pool; the pool
        otherwise counts individual user nodes.
        O(nodes + ledger entries), scalar indexes only, fixed-size return value.
        """
        from runtime_settings import primary_gateway_max_latency_ms_from_testing
        from tier1_protocols import physical_node_name
        from tier3_origin import is_tier3_user_pool_node
        from tier3_pool_retention import node_has_tier3_cache_revalidation_pending
        from tier3_verification_state import node_is_unverified_tcp_startup_candidate

        with self.lock:
            config = self.config
            limit = primary_gateway_max_latency_ms_from_testing(config.get("testing", {}))
            counts = {tier: {"total": 0, "usable": 0}
                      for tier in ("tier1", "tier2", "tier3", "exit")}
            pool = {"total": 0, "usable": 0}
            groups: dict[str, bool] = {}
            ledger = getattr(self, "_runtime_health_ledger", {})
            # Match exact-key then unique identity/pool fallback, as in
            # _runtime_health_entry_lookup_locked, without its per-node scan.
            matches: dict[tuple[str, str, str], int] = {}
            for entry in ledger.values():
                key = tuple(str(entry.get(k) or "") for k in ("tier", "identity", "pool_kind"))
                matches[key] = matches.get(key, 0) + 1
            for tier in counts:
                for node in self.runtime_nodes.get(tier, ()):
                    if tier == "tier3" and (
                        node_is_unverified_tcp_startup_candidate(node)
                        or node_has_tier3_cache_revalidation_pending(node)
                    ):
                        continue
                    kind = self._runtime_pool_kind_locked(tier, node)
                    identity = self._node_identity(node)
                    exact = self._runtime_health_ledger_key(tier, kind, identity, str(node.name or ""))
                    overlaid = ((bool(node.name) and ledger.get(exact) is not None)
                                or matches.get((tier, identity, kind), 0) == 1)
                    usable = node.status in {NodeStatus.ALIVE, NodeStatus.SLOW} and not overlaid
                    if tier != "tier3":
                        usable = usable and node.extra.get("latency_policy_state") != "over_limit"
                        if node.latency_ms is not None:
                            usable = usable and math.isfinite(node.latency_ms) and node.latency_ms <= limit
                    if tier == "tier1":
                        group = physical_node_name(node)
                        groups[group] = groups.get(group, False) or usable
                        continue
                    if tier != "tier3" or self._is_tier3_auto_pool_node(node):
                        counts[tier]["total"] += 1
                        counts[tier]["usable"] += int(usable)
                    if tier != "tier3" or is_tier3_user_pool_node(node):
                        pool["total"] += 1
                        pool["usable"] += int(usable)
            # §8u: a multi-protocol Tier1 node is one node in the tier count and in the pool
            counts["tier1"] = {"total": len(groups), "usable": sum(groups.values())}
            pool["total"] += counts["tier1"]["total"]
            pool["usable"] += counts["tier1"]["usable"]
            return {"tiers": counts, "pool": pool,
                    "runtime_generation": int(getattr(self, "runtime_generation", 0)),
                    "config_identity": id(config)}

    def tier3_pool_count_snapshot(self) -> Tier3PoolCountSnapshot:
        with self.lock:
            return self._tier3_pool_count_snapshot_locked()

    def tier3_auto_pool_count_snapshot(self) -> Tier3AutoPoolCountSnapshot:
        with self.lock:
            return self._tier3_auto_pool_count_snapshot_locked()

    def tier3_user_pool_health_snapshot(self) -> Tier3UserPoolHealthSnapshot:
        with self.lock:
            return self._tier3_user_pool_health_snapshot_locked()

    def tier3_startup_gate_progress(self) -> Tier3StartupGateProgress:
        with self.lock:
            snapshot = self._tier3_auto_pool_count_snapshot_locked()
            return Tier3StartupGateProgress(
                healthy=snapshot.healthy,
                required=self._tier3_min_alive_nodes(),
            )

    def _replace_tier3_pool_locked(
        self,
        nodes: list[Node],
        *,
        actor: str,
        reason: str,
        identity: str = "",
        allow_total_decrease: bool = False,
    ) -> bool:
        """Replace the canonical Tier3 pool and record its single owner/revision."""

        actor_name = str(actor or "unknown").strip() or "unknown"
        before_nodes = list(self.runtime_nodes["tier3"])
        replacement = nodes
        before = self._tier3_durable_pool_count_snapshot_locked(before_nodes)
        before_auto = self._tier3_durable_auto_pool_count_snapshot_locked(
            before_nodes
        )
        after_total = self._tier3_total_pool_total_count(replacement)
        after_healthy = count_healthy_nodes(
            self._tier3_total_pool_nodes_for_display(replacement)
        )
        after_auto_total = self._tier3_auto_pool_total_count(replacement)
        after_auto_healthy = count_healthy_nodes(
            self._tier3_auto_pool_nodes_for_display(replacement)
        )
        after_user_total = self._tier3_user_pool_total_count(replacement)
        after_user_healthy = count_healthy_nodes(
            self._tier3_user_pool_nodes_for_display(replacement)
        )
        auto_changed = (
            self._tier3_auto_pool_change_signature(before_nodes)
            != self._tier3_auto_pool_change_signature(replacement)
        )
        user_changed = (
            self._tier3_user_pool_change_signature(before_nodes)
            != self._tier3_user_pool_change_signature(replacement)
        )
        changed = auto_changed or user_changed
        forbidden_actors = {"repair", "export_overlay", "core_audit", "reachability"}
        unauthorized = bool(
            changed
            and (
                actor_name in forbidden_actors
                or (after_total < before.total and not allow_total_decrease)
            )
        )
        if unauthorized:
            report = ensure_tier3_collection_report(self)
            report["unauthorized_pool_mutation"] = {
                "actor": actor_name,
                "reason": str(reason or ""),
                "before_healthy": before.healthy,
                "before_total": before.total,
                "after_healthy": after_healthy,
                "after_total": after_total,
                "identity_hash": (
                    runtime_identity_hash(identity) if identity else ""
                ),
                "recorded_at": utc_now_iso(),
            }
            log_raw_diagnostic(self.logger, "error",
                "Rejected unauthorized Bastion Layer pool mutation "
                "(actor=%s reason=%s before=%s/%s after=%s/%s identity=%s)",
                actor_name,
                reason,
                before.healthy,
                before.total,
                after_healthy,
                after_total,
                runtime_identity_hash(identity) if identity else "none",
            )
            return False
        if not changed:
            self.runtime_nodes["tier3"] = replacement
            return True

        self.runtime_nodes["tier3"] = replacement
        if user_changed:
            self.tier3_user_pool_health_revision += 1
            report = ensure_tier3_collection_report(self)
            report["tier3a_health_revision"] = int(
                self.tier3_user_pool_health_revision
            )
            report["tier3a_healthy_count"] = int(after_user_healthy)
            report["tier3a_total_count"] = int(after_user_total)
        if not auto_changed:
            return True

        self.tier3_pool_revision += 1
        event = {
            "revision": int(self.tier3_pool_revision),
            "actor": actor_name,
            "reason": str(reason or ""),
            "before_healthy": before_auto.healthy,
            "before_total": before_auto.total,
            "after_healthy": after_auto_healthy,
            "after_total": after_auto_total,
            "overview_before_healthy": before.healthy,
            "overview_before_total": before.total,
            "overview_after_healthy": after_healthy,
            "overview_after_total": after_total,
            "identity_hash": (
                runtime_identity_hash(identity) if identity else ""
            ),
            "recorded_at": utc_now_iso(),
        }
        self.tier3_pool_mutation_ledger.append(event)
        del self.tier3_pool_mutation_ledger[:-128]
        report = ensure_tier3_collection_report(self)
        report["pool_revision"] = int(self.tier3_pool_revision)
        report["pool_healthy_count"] = after_auto_healthy
        report["pool_total_count"] = after_auto_total
        report["overview_healthy_count"] = after_healthy
        report["overview_total_count"] = after_total
        report["pool_last_mutation"] = dict(event)
        report["pool_mutation_ledger"] = [
            dict(item) for item in self.tier3_pool_mutation_ledger[-32:]
        ]
        self.logger.info(
            "Bastion Layer pool mutation committed "
            "(revision=%s actor=%s reason=%s before=%s/%s after=%s/%s identity=%s)",
            self.tier3_pool_revision,
            actor_name,
            reason,
            before_auto.healthy,
            before_auto.total,
            after_auto_healthy,
            after_auto_total,
            runtime_identity_hash(identity) if identity else "none",
        )
        return True

    def _tier3_stats(self) -> dict[str, Any]:
        with self.lock:
            nodes = list(self.runtime_nodes["tier3"])
            pool_count_snapshot = self._tier3_pool_count_snapshot_locked(nodes)
            auto_pool_count_snapshot = self._tier3_auto_pool_count_snapshot_locked(
                nodes
            )
            user_pool_health_snapshot = self._tier3_user_pool_health_snapshot_locked(
                nodes
            )
            startup_gate_progress = Tier3StartupGateProgress(
                healthy=auto_pool_count_snapshot.healthy,
                required=self._tier3_min_alive_nodes(),
            )
            report = (
                dict(self.tier3_last_collection_report)
                if isinstance(self.tier3_last_collection_report, dict)
                else {}
            )
            report["pool_revision"] = int(self.tier3_pool_revision)
            report["pool_healthy_count"] = int(auto_pool_count_snapshot.healthy)
            report["pool_total_count"] = int(auto_pool_count_snapshot.total)
            report["overview_healthy_count"] = int(pool_count_snapshot.healthy)
            report["overview_total_count"] = int(pool_count_snapshot.total)
            report["tier3a_health_revision"] = int(
                user_pool_health_snapshot.revision
            )
            if self.tier3_pool_mutation_ledger:
                report["pool_last_mutation"] = dict(
                    self.tier3_pool_mutation_ledger[-1]
                )
                report["pool_mutation_ledger"] = [
                    dict(item) for item in self.tier3_pool_mutation_ledger[-32:]
                ]
        runtime_truth = self._tier3_live_runtime_truth_fields()
        enabled = self._tier3_enabled()
        decision = self.tier3_controller.last_decision
        if self.last_collect_tier3 <= 0:
            next_collect_due_seconds = 0
        else:
            collect_interval = decision.collect_interval
            if enabled:
                collect_interval = self._tier3_pi_pressure_collect_interval(
                    decision=decision,
                    alive_count=self._tier3_auto_pool_healthy_count(nodes),
                    target_alive=self._tier3_background_target_alive_nodes(),
                )
            elapsed = max(0.0, time.monotonic() - self.last_collect_tier3)
            next_collect_due_seconds = max(0, int(collect_interval - elapsed))
        return tier3_stats_snapshot(
            enabled=enabled,
            nodes=nodes,
            report=report,
            tier3_source_count=self.tier3_source_count,
            background_target_alive=self._tier3_background_target_alive_nodes(),
            next_collect_due_seconds=next_collect_due_seconds,
            level=self.tier3_level,
            level_reason=self.tier3_level_reason,
            controller=self.tier3_controller.to_dict(),
            revival_count=self.tier3_revival_count,
            refresh_progress=self.tier3_refresh_progress,
            pool_count_snapshot=pool_count_snapshot,
            auto_pool_count_snapshot=auto_pool_count_snapshot,
            user_pool_health_snapshot=user_pool_health_snapshot,
            startup_gate_progress=startup_gate_progress,
            runtime_health_owner=self,
            runtime_truth=runtime_truth,
        )

    def _exit_stats(self) -> dict[str, Any]:
        nodes = self.runtime_effective_nodes("exit")
        return exit_stats_snapshot(configured=self._exit_tier_configured(), nodes=nodes)

    def _subscription_urls(self, host: str, port: int) -> dict[str, Any]:
        client_mode = str(self.client_config.get("mode", "v2ray")).lower()
        return subscription_urls(host, port, client_mode=client_mode)

    def _subscription_server_endpoint(self) -> tuple[Any, int]:
        subscription_config = subscription_server_runtime_config(self.config)
        return subscription_config.host, subscription_config.port

    def _runtime_tiers_snapshot(
        self,
        metrics: dict[str, Any],
        *,
        include_nodes: bool,
        tier3_enabled: bool,
    ) -> dict[str, Any]:
        return runtime_tiers_snapshot(
            metrics=metrics,
            tier3_stats=self._tier3_stats(),
            exit_stats=self._exit_stats(),
            last_check_at=self.last_check_at,
            tier2_last_refresh_at=self.tier2_last_refresh_at,
            tier3_last_collection_at=self.tier3_last_collection_at,
            tier3_source_count=self.tier3_source_count,
            exit_last_refresh_at=self.exit_last_refresh_at,
            include_nodes=include_nodes,
            tier1_nodes=self.runtime_effective_nodes("tier1"),
            tier1_protocol_groups=self._tier1_protocol_groups_snapshot() if include_nodes else [],
            tier2_nodes=self.runtime_effective_nodes("tier2"),
            tier3_nodes=self.runtime_effective_nodes(
                "tier3",
                self._tier3_main_pool_nodes_for_display(self.runtime_nodes["tier3"]),
            ),
            tier3_enabled=tier3_enabled,
            exit_nodes=self.runtime_effective_nodes("exit"),
        )

    def get_runtime_snapshot(self, *, include_nodes: bool = True) -> dict[str, Any]:
        with self.lock:
            metrics = self._state_metrics()
            subscription_host, subscription_port = self._subscription_server_endpoint()
            client_mode = str(self.client_config.get("mode", "v2ray")).lower()
            tier3_enabled = self._tier3_enabled()
            tiers = self._runtime_tiers_snapshot(
                metrics=metrics,
                include_nodes=include_nodes,
                tier3_enabled=tier3_enabled,
            )
            return runtime_snapshot_payload(
                metrics=metrics,
                uptime_seconds=int(max(0, time.monotonic() - self.start_time_monotonic)),
                started_at=self.start_time_utc,
                last_overall_check_at=self.last_overall_check_at,
                last_check_at=self.last_check_at,
                client_mode=client_mode,
                clash_config_path=str(self.client_config.get("clash_config_path", "")),
                kill_switch_state=self.kill_switch.get_state() if self.kill_switch else disabled_killswitch_state(),
                tiers=tiers,
                background_actions=self.background_actions,
                subscriptions=self._subscription_urls(subscription_host, subscription_port),
            )

    def get_tier3_nodes_snapshot(self) -> dict[str, Any]:
        snapshot = self.get_runtime_snapshot()
        tier3 = snapshot["tiers"]["tier3"]
        tier3["top_alive"] = [
            node.to_dict()
            for node in self.get_nodes_for_subscription(
                "tier3",
                limit=subscription_server_runtime_config(self.config).tier3_limit,
            )
        ]
        return tier3

    def _run_background_action(self, name: str, action: Callable[[], dict[str, Any] | None]) -> dict[str, Any]:
        with self.lock:
            state = self.background_actions[name]
            accepted, next_state = start_background_action_state(state, started_at=utc_now_iso())
            if not accepted:
                return {"accepted": False, "action": name, "status": "running"}
            self.background_actions[name] = next_state

        def worker() -> None:
            error: str | None = None
            result: dict[str, Any] | None = None
            try:
                action_result = action()
                if isinstance(action_result, dict):
                    result = action_result
            except Exception as exc:
                error = str(exc)
                log_raw_diagnostic(self.logger, "exception", "Background action %s failed", name)
            finally:
                with self.lock:
                    self.background_actions[name] = finish_background_action_state(
                        self.background_actions[name],
                        completed_at=utc_now_iso(),
                        error=error,
                        result=result,
                    )

        thread = threading.Thread(target=worker, name=f"proxy-manager-{name}", daemon=True)
        thread.start()
        return {"accepted": True, "action": name, "status": "started"}

    def _tier3a_user_nodes_snapshot(self) -> list[Node]:
        with self.lock:
            return [
                node.clone()
                for node in self.runtime_nodes["tier3"]
                if not self._is_tier3_auto_pool_node(node)
            ]

    def _active_tier3_validation_domain_for_health(
        self,
    ) -> Tier3ValidationDomain | None:
        with self._tier3_active_stream_lock:
            domains = tuple(self._tier3_active_validation_domains)
        for domain in domains:
            try:
                if domain.snapshot().stop_status == "running":
                    return domain
            except Exception:
                continue
        return None

    def _wait_for_tier3_validation_domain_for_health(
        self,
        timeout_seconds: float = 2.0,
    ) -> Tier3ValidationDomain | None:
        deadline = time.monotonic() + max(0.0, float(timeout_seconds))
        while not self.closed and not self._tier3_cancel_event.is_set():
            domain = self._active_tier3_validation_domain_for_health()
            if domain is not None:
                return domain
            with self.lock:
                action = dict(self.background_actions.get("tier3_collect") or {})
            if not bool(action.get("running")) or time.monotonic() >= deadline:
                return None
            time.sleep(0.025)
        return None

    def _tier3_collect_action_running(self) -> bool:
        with self.lock:
            action = dict(self.background_actions.get("tier3_collect") or {})
        return bool(action.get("running"))

    def wait_for_tier3_expansion_ready(
        self,
        timeout_seconds: float = 0.5,
    ) -> dict[str, Any]:
        """Wait only for the expansion/session control plane to become usable."""

        deadline = time.monotonic() + max(0.0, float(timeout_seconds))
        while not self.closed:
            with self._tier3_active_stream_lock:
                refresh_epoch = int(self._tier3_refresh_epoch)
                session_started = bool(
                    self._tier3_expansion_session_started_epoch == refresh_epoch
                )
                source_ready = bool(
                    self._tier3_source_supervisor_ready_epoch == refresh_epoch
                )
                session_started_at = float(
                    self._tier3_expansion_session_started_at or 0.0
                )
                source_ready_at = float(
                    self._tier3_source_supervisor_ready_at or 0.0
                )
            if session_started and source_ready:
                return {
                    "ready": True,
                    "refresh_epoch": refresh_epoch,
                    "session_started": True,
                    "source_supervisor_ready": True,
                    "session_started_at_monotonic": session_started_at,
                    "source_supervisor_ready_at_monotonic": source_ready_at,
                }
            remaining = deadline - time.monotonic()
            if remaining <= 0.0:
                return {
                    "ready": False,
                    "refresh_epoch": refresh_epoch,
                    "session_started": session_started,
                    "source_supervisor_ready": source_ready,
                    "session_started_at_monotonic": session_started_at,
                    "source_supervisor_ready_at_monotonic": source_ready_at,
                }
            wait_event = (
                self._tier3_source_supervisor_ready_event
                if session_started
                else self._tier3_expansion_session_started_event
            )
            wait_event.wait(min(0.025, remaining))
        return {
            "ready": False,
            "refresh_epoch": int(self._tier3_refresh_epoch),
            "session_started": False,
            "source_supervisor_ready": False,
            "stopped": True,
        }

    def _schedule_tier3a_health_retry(self, delay_seconds: float = 1.0) -> None:
        with self._tier3a_health_waiters_lock:
            if self.closed or self._tier3a_health_retry_scheduled:
                return
            self._tier3a_health_retry_scheduled = True

        def retry() -> None:
            with self._tier3a_health_waiters_lock:
                self._tier3a_health_retry_scheduled = False
            if not self.closed and not self._tier3_cancel_event.is_set():
                self.trigger_tier3a_health_check()

        timer = threading.Timer(max(0.1, float(delay_seconds)), retry)
        timer.daemon = True
        timer.start()

    def _receive_tier3a_health_terminal(
        self,
        node: Node,
        terminal: ValidationTerminal,
    ) -> None:
        if terminal.purpose is not Tier3ValidationPurpose.USER_POOL_HEALTH:
            return
        with self._tier3a_health_waiters_lock:
            waiter = self._tier3a_health_waiters.get(terminal.candidate_digest)
            if waiter is None or waiter.get("terminal") is not None:
                return
            waiter["node"] = node.clone()
            waiter["terminal"] = terminal
            event = waiter.get("event")
        if isinstance(event, threading.Event):
            event.set()

    @staticmethod
    def _tier3a_result_status(
        terminal_kind: Tier3TerminalKind,
        tested_node: Node,
    ) -> tuple[NodeStatus, bool]:
        if terminal_kind is Tier3TerminalKind.PASS:
            return tested_node.status, False
        if terminal_kind is Tier3TerminalKind.CANDIDATE_FAIL:
            return NodeStatus.DEAD, False
        return NodeStatus.SUSPICIOUS, True

    def _apply_tier3a_health_result(
        self,
        *,
        identity: str,
        config_digest: str,
        tested_node: Node,
        outcome: Tier3TerminalKind,
        failure_class: str,
        runtime_recheck: dict[str, Any] | None = None,
        check_context: CheckContext | None = None,
    ) -> Tier3AHealthCheckResult | None:
        status, pending_recheck = self._tier3a_result_status(outcome, tested_node)
        checked_at = tested_node.last_checked_at or utc_now_iso()
        updated = tested_node.clone()
        updated.status = status
        updated.last_checked_at = checked_at
        updated.extra["tier3a_health_checked"] = True
        updated.extra["tier3a_health_outcome"] = outcome.value
        updated.extra["tier3a_health_pending_recheck"] = pending_recheck
        updated.extra["tier3a_health_failure_class"] = str(failure_class or "")
        if status is NodeStatus.DEAD:
            updated.latency_ms = None
            updated.suspicious_reason = str(
                failure_class or "tier3a_mixed_port_validation_failed"
            )
        elif pending_recheck:
            updated.latency_ms = None
            updated.suspicious_reason = str(
                failure_class or "tier3a_health_pending_recheck"
            )
        else:
            updated.suspicious_reason = None

        with self.lock:
            if check_context is not None and not self._health_check_context_current_locked(check_context):
                return None
            if runtime_recheck is not None and not self._runtime_recheck_matches_active(
                runtime_recheck
            ):
                return None
            nodes = list(self.runtime_nodes["tier3"])
            index = self._runtime_node_index(nodes, identity)
            if index is None or self._is_tier3_auto_pool_node(nodes[index]):
                return None
            current_digest = tier3_candidate_config_digest(nodes[index])
            if current_digest != config_digest:
                return None
            nodes[index] = updated
            if not self._replace_tier3_pool_locked(
                self._sort_tier3_nodes(nodes),
                actor="user_pool_health",
                reason="Tier3A mixed-port health check",
                identity=identity,
            ):
                return None
            if check_context is not None:
                self._record_health_check_commit_locked(check_context)
            payload = None
            if check_context is not None and runtime_recheck is None:
                verdict = "pending" if pending_recheck else "pass" if status in {NodeStatus.ALIVE, NodeStatus.SLOW} else "fail"
                if check_context.incident.get("incident_id"):
                    payload = self._complete_runtime_leaf_recheck(check_context.to_request(), verdict=verdict, status=status, emit=False)
                else:
                    payload = self._health_check_result_payload(check_context, updated, verdict=verdict, transition={
                        "accepted": True, "changed": True,
                        "action": {"pass": "recovered", "fail": "transferred", "pending": "pending"}[verdict],
                    })
        if payload is not None:
            self._emit_runtime_leaf_recheck_result(payload)
        return Tier3AHealthCheckResult(
            identity=identity,
            config_digest=config_digest,
            outcome=outcome,
            status=status,
            checked_at=checked_at,
            failure_class=str(failure_class or ""),
            latency_ms=(
                float(updated.latency_ms)
                if updated.latency_ms is not None
                else None
            ),
            pending_recheck=pending_recheck,
        )

    def _tier3a_tcp_health_result(
        self,
        original: Node,
        tested: Node,
        *,
        runtime_recheck: dict[str, Any] | None = None,
        check_context: CheckContext | None = None,
    ) -> Tier3AHealthCheckResult | None:
        identity = self._node_identity(original)
        config_digest = tier3_candidate_config_digest(original)
        failure_stage = str(tested.extra.get("tier3_failure_stage") or "")
        deferred = failure_stage in {"tcp_deferred", "tcp_cancelled"}
        return self._apply_tier3a_health_result(
            identity=identity,
            config_digest=config_digest,
            tested_node=tested,
            outcome=(
                Tier3TerminalKind.CENSORED
                if deferred
                else Tier3TerminalKind.CANDIDATE_FAIL
            ),
            failure_class=failure_stage or "tier3a_tcp_unreachable",
            runtime_recheck=runtime_recheck,
            check_context=check_context,
        )

    def _run_tier3a_process_health_check(
        self,
        node: Node,
        *,
        runtime_recheck: dict[str, Any] | None = None,
        check_context: CheckContext | None = None,
    ) -> Tier3AHealthCheckResult | None:
        if check_context is None:
            check_context = self._capture_health_check_context(
                "tier3", node, origin="scheduled" if runtime_recheck is None else "incident_initial", request=runtime_recheck,
            )
        identity = self._node_identity(node)
        config_digest = tier3_candidate_config_digest(node)
        testing_config = self._testing_config_for_node_checks()
        tcp_outcome = self._run_async(
            scan_tier3_tcp_candidates(
                [node.clone()],
                testing_config=testing_config,
                logger=self.logger,
                concurrency=1,
                cancel_event=self._tier3_cancel_event,
            ),
            cancel_event=self._tier3_cancel_event,
        )
        if not tcp_outcome.nodes:
            deferred = node.clone()
            deferred.status = NodeStatus.SUSPICIOUS
            deferred.last_checked_at = utc_now_iso()
            return self._apply_tier3a_health_result(
                identity=identity,
                config_digest=config_digest,
                tested_node=deferred,
                outcome=Tier3TerminalKind.CENSORED,
                failure_class="tier3a_tcp_no_result",
                runtime_recheck=runtime_recheck,
                check_context=check_context,
            )
        tcp_tested = tcp_outcome.nodes[0]
        if tcp_tested.status not in {NodeStatus.ALIVE, NodeStatus.SLOW}:
            return self._tier3a_tcp_health_result(
                node,
                tcp_tested,
                runtime_recheck=runtime_recheck,
                check_context=check_context,
            )

        with self._tier3a_health_waiters_lock:
            self._tier3a_health_check_sequence += 1
            check_sequence = int(self._tier3a_health_check_sequence)
        transaction_nonce = (
            f"{self.runtime_generation}:{check_sequence}:{time.monotonic_ns()}"
        )
        domain = self._wait_for_tier3_validation_domain_for_health()
        owned_domain = domain is None
        if domain is None and self._tier3_collect_action_running():
            pending = tcp_tested.clone()
            pending.status = NodeStatus.SUSPICIOUS
            pending.last_checked_at = utc_now_iso()
            result = self._apply_tier3a_health_result(
                identity=identity,
                config_digest=config_digest,
                tested_node=pending,
                outcome=Tier3TerminalKind.CENSORED,
                failure_class="tier3a_auto_validation_domain_starting",
                runtime_recheck=runtime_recheck,
                check_context=check_context,
            )
            self._schedule_tier3a_health_retry()
            return result
        if domain is None:
            settings = process_validator_settings(testing_config)

            def reject_health_admission(
                _node: Node,
                _report: dict[str, Any],
                intent: AdmissionIntent,
            ) -> AdmissionRejected:
                return AdmissionRejected(
                    refresh_epoch=intent.refresh_epoch,
                    candidate_digest=intent.candidate_digest,
                    lease_id=intent.lease_id,
                    sequence=intent.sequence,
                    reason="user_pool_health_has_no_admission_permission",
                )

            domain = Tier3ValidationDomain(
                refresh_epoch=(
                    f"tier3a-health:{self.runtime_generation}:{check_sequence}"
                ),
                binary_path=str(settings["binary_path"]),
                probe_urls=list(settings["probe_urls"]),
                expected_statuses=set(settings["expected_statuses"]),
                probe_timeout_seconds=float(settings["probe_timeout_seconds"]),
                slow_threshold_ms=slow_threshold_ms_from_testing(testing_config),
                commit_node=reject_health_admission,
                terminal_observer=self._receive_tier3a_health_terminal,
                logger=self.logger,
                min_workers=1,
                max_workers=1,
                temp_parent=str(settings["temp_parent"]),
                ipv6=bool(settings["ipv6"]),
                # User-pool health rechecks apply the same mainstream HTTPS
                # admission gate, so a pool node that fails it is evicted.
                confirm_urls=list(settings["confirm_urls"]),
            )
            with self._tier3_active_stream_lock:
                if self.closed or self._tier3_cancel_event.is_set():
                    return None
                self._tier3_active_validation_domains.add(domain)
            if not domain.start():
                stop_status = domain.stop(
                    timeout_seconds=2.0,
                    owner="tier3a-health-start",
                )
                self._release_stopped_tier3_validation_domain(
                    domain,
                    stop_status,
                )
                return None

        candidate_digest = domain.candidate_digest_for_submission(
            tcp_tested,
            purpose=Tier3ValidationPurpose.USER_POOL_HEALTH,
            transaction_nonce=transaction_nonce,
        )
        waiter_event = threading.Event()
        with self._tier3a_health_waiters_lock:
            self._tier3a_health_waiters[candidate_digest] = {
                "event": waiter_event,
                "node": None,
                "terminal": None,
            }
        submitted = domain.submit(
            tcp_tested,
            {"tier3a_health_check": True},
            purpose=Tier3ValidationPurpose.USER_POOL_HEALTH,
            transaction_nonce=transaction_nonce,
        )
        if not submitted:
            waiter_event.set()
        settings = process_validator_settings(testing_config)
        timeout_seconds = max(
            15.0,
            5.0
            + len(settings["probe_urls"]) * 7.0
            # One passing slice may add its mainstream HTTPS confirm.
            + len(settings["confirm_urls"]) * 5.0,
        )
        waiter_event.wait(timeout_seconds)
        with self._tier3a_health_waiters_lock:
            waiter = self._tier3a_health_waiters.pop(candidate_digest, {})
        terminal = waiter.get("terminal")
        tested_node = waiter.get("node")
        if owned_domain:
            stop_status = domain.stop(
                timeout_seconds=3.0,
                owner="tier3a-health-complete",
            )
            self._release_stopped_tier3_validation_domain(domain, stop_status)
        if not isinstance(terminal, ValidationTerminal) or not isinstance(
            tested_node,
            Node,
        ):
            pending = tcp_tested.clone()
            pending.status = NodeStatus.SUSPICIOUS
            pending.last_checked_at = utc_now_iso()
            return self._apply_tier3a_health_result(
                identity=identity,
                config_digest=config_digest,
                tested_node=pending,
                outcome=Tier3TerminalKind.CENSORED,
                failure_class="tier3a_validation_timeout_or_cancelled",
                runtime_recheck=runtime_recheck,
                check_context=check_context,
            )
        return self._apply_tier3a_health_result(
            identity=identity,
            config_digest=config_digest,
            tested_node=tested_node,
            outcome=terminal.kind,
            failure_class=str(terminal.reason or terminal.kind.value),
            runtime_recheck=runtime_recheck,
            check_context=check_context,
        )

    def _check_tier3a_user_pool_health(self) -> list[Node]:
        checked: list[Node] = []
        if not self._tier3_enabled():
            return checked
        if not self._tier3a_health_check_lock.acquire(blocking=False):
            return checked
        try:
            for node in self._tier3a_user_nodes_snapshot():
                if self.closed or self._tier3_cancel_event.is_set():
                    break
                result = self._run_tier3a_process_health_check(node)
                if result is None:
                    continue
                with self.lock:
                    current = next(
                        (
                            item.clone()
                            for item in self.runtime_nodes["tier3"]
                            if self._node_identity(item) == result.identity
                        ),
                        None,
                    )
                if current is not None:
                    checked.append(current)
            return checked
        finally:
            self.last_tier3a_health_check_monotonic = time.monotonic()
            self.last_tier3a_health_check_at = utc_now_iso()
            self._tier3a_health_check_lock.release()

    def trigger_tier3a_health_check(self) -> dict[str, Any]:
        def action() -> dict[str, Any]:
            tested = self._check_tier3a_user_pool_health()
            self.evaluate_state()
            summary = self._test_nodes_result_summary("tier3", tested)
            summary["scope"] = "tier3a_health"
            return summary

        return self._run_background_action("tier3a_health", action)

    def trigger_test_all(self) -> dict[str, Any]:
        def action() -> dict[str, Any]:
            tier1_nodes = self.check_tier1() or []
            tier2_nodes = self.check_tier2(force_remote_refresh=False) or []
            tier3a_nodes = self._check_tier3a_user_pool_health()
            self.evaluate_state()
            tiers = {
                "tier1": self._test_nodes_result_summary("tier1", tier1_nodes),
                "tier2": self._test_nodes_result_summary("tier2", tier2_nodes),
                "tier3": self._test_nodes_result_summary("tier3", tier3a_nodes),
            }
            total = sum(summary["total"] for summary in tiers.values())
            healthy = sum(summary["healthy"] for summary in tiers.values())
            fastest_values = [
                summary["fastest_latency_ms"]
                for summary in tiers.values()
                if summary.get("fastest_latency_ms") is not None
            ]
            return {
                "scope": "all",
                "total": total,
                "healthy": healthy,
                "fastest_latency_ms": min(fastest_values) if fastest_values else None,
                "tiers": tiers,
            }

        return self._run_background_action("test_all", action)

    def trigger_test_tier(self, tier_id: str) -> dict[str, Any]:
        tier_id = str(tier_id or "").strip()

        def action() -> dict[str, Any]:
            if tier_id == "tier1":
                tested = self.check_tier1() or []
            elif tier_id == "tier2":
                tested = self.check_tier2(force_remote_refresh=False) or []
            elif tier_id == "tier3":
                tested = self._check_tier3a_user_pool_health()
            elif tier_id == "exit":
                tested = self.check_exit(force_remote_refresh=False) or []
            else:
                raise ValueError(f"unsupported tier: {tier_id}")
            self.evaluate_state()
            summary = self._test_nodes_result_summary(tier_id, tested)
            summary["scope"] = "tier"
            return summary

        return self._run_background_action("test_tier", action)

    def trigger_test_node(self, node_identity: str) -> dict[str, Any]:
        node_identity = str(node_identity or "").strip()
        if not node_identity:
            raise ValueError("node identity is required")
        tier_id = node_identity.split("|", 1)[0]
        if tier_id == "tier3":
            with self.lock:
                target_node = next(
                    (node for node in self.runtime_nodes["tier3"] if self._node_identity(node) == node_identity),
                    None,
                )
            if target_node is None:
                raise KeyError("node not found")
            if self._is_tier3_auto_pool_node(target_node):
                return {
                    "accepted": False,
                    "action": "test_node",
                    "status": "unsupported",
                    "reason": "tier3_auto_pool_self_check",
                }

        def action() -> dict[str, Any]:
            if tier_id == "tier3":
                with self.lock:
                    current = next(
                        (
                            node.clone()
                            for node in self.runtime_nodes["tier3"]
                            if self._node_identity(node) == node_identity
                            and not self._is_tier3_auto_pool_node(node)
                        ),
                        None,
                    )
                if current is None:
                    raise KeyError("node not found")
                self._run_tier3a_process_health_check(current)
                with self.lock:
                    tested_node = next(
                        (
                            node.clone()
                            for node in self.runtime_nodes["tier3"]
                            if self._node_identity(node) == node_identity
                        ),
                        None,
                    )
                if tested_node is None:
                    raise KeyError("node not found")
            else:
                tested_node = self._test_runtime_node_by_identity(
                    tier_id,
                    node_identity,
                )
            self.evaluate_state()
            return self._test_node_result_summary(tier_id, tested_node)

        return self._run_background_action("test_node", action)

    def _runtime_node_index(self, nodes: list[Node], node_identity: str) -> int | None:
        return runtime_node_index(
            nodes,
            node_identity,
            identity_fn=self._node_identity,
        )

    def _test_runtime_node_by_identity(
        self,
        tier_id: str,
        node_identity: str,
        *,
        mark_layer_check: bool = True,
        persist_result: bool = True,
        pool_kind: str = "",
        proxy_name: str = "",
    ) -> Node:
        if tier_id not in self.runtime_nodes:
            raise ValueError(f"unsupported tier: {tier_id}")
        with self.operation_lock:
            with self.lock:
                nodes = list(self.runtime_nodes[tier_id])
                target_index = next(
                    (
                        item_index
                        for item_index, item in enumerate(nodes)
                        if self._node_identity(item) == node_identity
                        and (not proxy_name or str(item.name or "") == proxy_name)
                        and (
                            not pool_kind
                            or self._runtime_pool_kind_locked(tier_id, item) == pool_kind
                        )
                    ),
                    None,
                )
            if target_index is None:
                raise KeyError("node not found")
            if tier_id == "tier3" and self._is_tier3_auto_pool_node(nodes[target_index]):
                raise ValueError("tier3 auto pool nodes are checked by background self-check")
            tested = self._run_async(
                test_nodes(
                    [nodes[target_index]],
                    testing_config=self._testing_config_for_node_checks(),
                    logger=self.logger,
                    full_validation_enabled=self._full_validation_enabled(),
                    gateway_nodes=self._gateway_nodes_for_testing(tier_id),
                )
            )
            if not tested:
                raise RuntimeError("node test returned no result")
            if persist_result:
                self._replace_tested_runtime_node(
                    tier_id,
                    node_identity,
                    tested[0],
                    mark_layer_check=mark_layer_check,
                    pool_kind=pool_kind,
                    proxy_name=proxy_name,
                )
            return tested[0]

    def _test_nodes_result_summary(self, tier_id: str, nodes: list[Node]) -> dict[str, Any]:
        status_counts: dict[str, int] = {}
        latencies: list[float] = []
        for node in nodes:
            status = node.status.value if isinstance(node.status, NodeStatus) else str(node.status or "")
            status_counts[status] = status_counts.get(status, 0) + 1
            if node.latency_ms is not None:
                latencies.append(float(node.latency_ms))
        summary_nodes = self._tier3_main_pool_nodes_for_display(nodes) if tier_id == "tier3" else nodes
        return {
            "tier": tier_id,
            "total": len(summary_nodes),
            "healthy": count_healthy_nodes(summary_nodes),
            "fastest_latency_ms": min(latencies) if latencies else None,
            "status_counts": status_counts,
        }

    def _test_node_result_summary(self, tier_id: str, node: Node) -> dict[str, Any]:
        status = node.status.value if isinstance(node.status, NodeStatus) else str(node.status or "")
        return {
            "scope": "node",
            "tier": tier_id,
            "node": node.name,
            "status": status,
            "latency_ms": node.latency_ms,
            "healthy": 1 if node.status in {NodeStatus.ALIVE, NodeStatus.SLOW} else 0,
            "total": 1,
        }

    def _replace_tested_runtime_node(
        self,
        tier_id: str,
        node_identity: str,
        tested_node: Node,
        *,
        mark_layer_check: bool = True,
        pool_kind: str = "",
        proxy_name: str = "",
        check_context: CheckContext | None = None,
    ) -> None:
        with self.lock:
            if check_context is not None and not self._health_check_context_current_locked(check_context):
                return
            current_nodes = list(self.runtime_nodes[tier_id])
            replace_index = next(
                (
                    item_index
                    for item_index, item in enumerate(current_nodes)
                    if self._node_identity(item) == node_identity
                    and (not proxy_name or str(item.name or "") == proxy_name)
                    and (
                        not pool_kind
                        or self._runtime_pool_kind_locked(tier_id, item) == pool_kind
                    )
                ),
                None,
            )
            if replace_index is None:
                raise KeyError("node not found")
            if check_context is None and self._runtime_audit_failure_protected(current_nodes[replace_index], tested_node):
                return
            current_nodes[replace_index] = self._clear_runtime_audit_failure_extra_if_recovered(tested_node)
            if tier_id == "tier3":
                self._replace_tier3_pool_locked(
                    self._sort_tier3_nodes(current_nodes),
                    actor="targeted_pool_rule",
                    reason="explicit pool node validation",
                    identity=node_identity,
                )
            else:
                self.runtime_nodes[tier_id] = sort_nodes_for_use(current_nodes)
            if mark_layer_check:
                self._mark_check(tier_id)
            if tier_id == "tier3" and mark_layer_check:
                self._save_tier3_snapshot(self.runtime_nodes[tier_id], self.tier3_source_count)

    def trigger_tier2_refresh(self) -> dict[str, Any]:
        def action() -> None:
            self.check_tier2(force_remote_refresh=True)
            self.evaluate_state()

        return self._run_background_action("tier2_refresh", action)

    def trigger_tier3_collect(
        self,
        *,
        startup_mode: bool = False,
        include_pool_check: bool = False,
    ) -> dict[str, Any]:
        with self._tier3_active_stream_lock:
            if self.closed:
                return {
                    "accepted": False,
                    "action": "tier3_collect",
                    "status": "stopped",
                }
            trigger_epoch = int(self._tier3_refresh_epoch)

        def action() -> None:
            previous_alive = self._tier3_auto_pool_healthy_count(self.runtime_nodes["tier3"])
            nodes, _raw_alive_count = self.refresh_tier3(
                startup_mode=startup_mode,
                include_pool_check=include_pool_check,
            )
            if not self._tier3_refresh_session_is_active(trigger_epoch):
                return
            alive_count = self._tier3_auto_pool_healthy_count(nodes)
            if alive_count != previous_alive:
                self.last_pool_alive_count = alive_count
            self.evaluate_state()

        return self._run_background_action("tier3_collect", action)

    def prune_tier3_pool(self) -> dict[str, Any]:
        with self.operation_lock:
            with self.lock:
                before = len(self.runtime_nodes["tier3"])
                max_pool_size = self._tier3_max_pool_size()
                kept = [
                    node
                    for node in self.runtime_nodes["tier3"]
                    if node.status not in {NodeStatus.DEAD, NodeStatus.SUSPICIOUS}
                ]
                kept = self._sort_tier3_nodes(kept)[:max_pool_size]
                removed = before - len(kept)
                self._replace_tier3_pool_locked(
                    kept,
                    actor="manual_prune",
                    reason="manual Tier3 prune",
                    allow_total_decrease=True,
                )
                self._save_tier3_snapshot(kept, self.tier3_source_count)
                self.last_pool_alive_count = self._tier3_auto_pool_healthy_count(kept)
                committed = list(self.runtime_nodes["tier3"])
        if removed:
            # A manual prune is a membership change like any eviction: the
            # runtime must hear about it so the loaded Core drops the members.
            self._notify_tier3_pool_committed(
                committed,
                startup_mode=False,
                alive_count=count_healthy_nodes(committed),
                metadata={"actor": "manual_prune"},
            )
        return {"before": before, "after": len(kept), "removed": removed}

    def trigger_tier3_prune(self) -> dict[str, Any]:
        def action() -> None:
            self.prune_tier3_pool()
            self.evaluate_state()

        return self._run_background_action("tier3_prune", action)

    def trigger_tier3_targeted_recheck(self) -> dict[str, Any]:
        def action() -> dict[str, Any]:
            result = self._run_tier3_targeted_rechecks()
            self.evaluate_state()
            return result

        return self._run_background_action("tier3_targeted_recheck", action)

    def trigger_exit_refresh(self) -> dict[str, Any]:
        def action() -> None:
            self.check_exit(force_remote_refresh=True)
            self.evaluate_state()

        return self._run_background_action("exit_refresh", action)

    def set_killswitch_manual(self, enabled: bool) -> dict[str, Any]:
        if not self.kill_switch:
            return {"accepted": False, "status": "unavailable"}
        state = self.kill_switch.get_state()
        if state["state"] == "disabled":
            return {"accepted": False, "status": "disabled", "killswitch": state}
        if enabled:
            already_forced = state["manual_override"] == "forced_on"
            self.kill_switch.force_on()
            if not already_forced:
                self.alerts.send_event(kill_switch_manual_override_event())
            return {"accepted": True, "status": "forced_on", "killswitch": self.kill_switch.get_state()}
        had_override = state["manual_override"] == "forced_on" or state["active"]
        self.kill_switch.force_off()
        if had_override:
            self.alerts.send_event(kill_switch_manual_clear_event())
        self.evaluate_state()
        return {"accepted": True, "status": "forced_off", "killswitch": self.kill_switch.get_state()}

    def _run_due_tier3_cycle(
        self,
        *,
        now: float,
        check_interval: int,
        collect_interval: int,
    ) -> None:
        if not self._tier3_enabled():
            return
        if self.tier3_targeted_recheck_queue:
            self.trigger_tier3_targeted_recheck()
        check_due = self._is_due("tier3", now, check_interval)
        tier3a_check_due = (
            self.last_tier3a_health_check_monotonic <= 0.0
            or now - self.last_tier3a_health_check_monotonic >= check_interval
        )
        if tier3a_check_due and self._tier3_user_pool_total_count(
            self.runtime_nodes["tier3"]
        ):
            self.trigger_tier3a_health_check()
        if self._tier3_startup_supply_is_terminal():
            # Terminal startup supply is not a polling state. Retained bad
            # nodes continue their periodic health checks so recovery can
            # satisfy the floor, but remote roots are not fetched again until
            # a new explicit startup/refresh or formal Core becomes ready.
            if check_due:
                self._check_tier3_existing_pool_only()
            return
        include_pool_check = bool(self._tier3_auto_pool_total_count(self.runtime_nodes["tier3"]) and check_due)
        if self._tier3_background_expansion_pending(self.runtime_nodes["tier3"]):
            action = self.background_actions.get("tier3_collect", {})
            action_running = bool(
                isinstance(action, dict) and action.get("running")
            )
            if not action_running:
                self.trigger_tier3_collect(
                    include_pool_check=include_pool_check,
                )
            return
        if (now - self.last_collect_tier3) >= collect_interval:
            self.trigger_tier3_collect(include_pool_check=include_pool_check)
            return
        if check_due:
            self.check_tier3(force_collect=False)

    def _run_due_urgent_checks(self, *, now: float, interval: int = 5) -> None:
        force_remote_refresh = self._tier2_degraded_remote_refresh_due(now=now)
        if force_remote_refresh or self._tier2_urgent_recheck_due(now=now, interval=interval):
            self._run_urgent_check(
                "tier2",
                lambda: self.check_tier2(force_remote_refresh=force_remote_refresh),
            )
        tier3_supply_terminal = self._tier3_startup_supply_is_terminal()
        force_tier3_collect = bool(
            not tier3_supply_terminal
            and self._tier3_user_subscription_collect_due(now=now)
        )
        tier3_urgent_recheck = self._tier3_urgent_recheck_due(
            now=now,
            interval=interval,
        )
        if force_tier3_collect or tier3_urgent_recheck:
            self._run_urgent_check(
                "tier3",
                (
                    self._check_tier3_existing_pool_only
                    if tier3_supply_terminal
                    else lambda: self.check_tier3(
                        force_collect=force_tier3_collect
                    )
                ),
            )
        if self._exit_urgent_recheck_due(now=now, interval=interval):
            self._run_urgent_check(
                "exit",
                lambda: self.check_exit(force_remote_refresh=False),
            )

    def run_cycle(self) -> dict[str, Any]:
        if self.closed:
            with self.lock:
                metrics = self._state_metrics()
            return {
                "active_tier": metrics["active_tier"],
                "mode": metrics["mode"],
                "tier1_alive": metrics["tier1_alive"],
                "tier2_alive": metrics["tier2_alive"],
                "tier3_alive": metrics["tier3_alive"],
                "exit_alive": metrics["exit_alive"],
                "final_exit": metrics["final_exit"],
            }
        now = time.monotonic()
        tier1_interval = self._tier_interval("tier1")
        tier2_interval = self._tier_interval("tier2")
        tier3_interval = self._tier_interval("tier3")
        exit_interval = self._tier_interval("exit")
        tier3_collect_interval = self._tier3_run_cycle_collect_interval()

        if self._is_due("tier1", now, tier1_interval):
            self.check_tier1()
        if self._is_due("tier2", now, tier2_interval):
            self.check_tier2(force_remote_refresh=True)
        self._run_due_tier3_cycle(
            now=now,
            check_interval=tier3_interval,
            collect_interval=tier3_collect_interval,
        )

        if self._exit_active() and self._is_due("exit", now, exit_interval):
            self.check_exit(force_remote_refresh=True)

        self._run_due_urgent_checks(now=now)

        return self.evaluate_state()
